const MWB_LAYOUTS = [
  {id:'default', label:'默认排版'},
  {id:'two-column', label:'双列排版'},
  {id:'trial', label:'试听排版'},
];

function mwbNormalizeLayout(value) {
  return MWB_LAYOUTS.some(layout => layout.id === value) ? value : 'default';
}

function mwbTrialDetailsFromMetadata(metadata = {}) {
  // Generated handouts store an independent course title (including a blank) in titile.
  const titleKeys = metadata.note_type === 'handout'
    ? ['titile', 'title', '课题名称']
    : ['title', '课题名称', 'titile'];
  const fields = {
    teacher:['author'],
    student:['学生', '学生姓名', 'student', 'student_name', 'students'],
    time:['上课时间', '授课时间', 'lesson_time', 'class_time', 'time', 'date'],
    subject:['subject', '学科'],
    grade:['年级', 'grade'],
    title:titleKeys,
    objectives:['教学目标', '学习目标', 'learning_objectives', 'objectives'],
  };
  const text = value => {
    if (typeof value !== 'string' && typeof value !== 'number') return '';
    const result = String(value).trim();
    return result === '待补' ? '' : result;
  };
  const details = {};
  for (const [field, keys] of Object.entries(fields)) {
    // A present but empty primary property is intentional; do not resurrect
    // an outdated compatibility field, filename or invented default.
    const key = keys.find(key => Object.prototype.hasOwnProperty.call(metadata, key));
    const value = key === undefined ? null : metadata[key];
    details[field] = Array.isArray(value)
      ? value.map(text).filter(Boolean).join(field === 'objectives' ? '\n' : '、')
      : text(value);
  }
  if (!details.teacher) details.teacher = '孙老师';
  return details;
}

// Plain text only: course information must never introduce executable HTML,
// answer markers or Markdown structure into the rendered handout.
function mwbCreateTrialHeader(doc, details = {}) {
  const header = doc.createElement('header');
  header.className = 'mwb-trial-header';
  const table = doc.createElement('table');
  table.className = 'mwb-trial-table';
  table.setAttribute('aria-label', '试听课信息');
  const cols = doc.createElement('colgroup');
  for (const width of [11, 12, 11, 12, 13, 41]) {
    const col = doc.createElement('col'); col.style.width = width + '%'; cols.appendChild(col);
  }
  table.appendChild(cols);
  const body = doc.createElement('tbody');
  const row = entries => {
    const tr = doc.createElement('tr');
    for (const [label, value, span = 1] of entries) {
      const cell = doc.createElement(label ? 'th' : 'td');
      if (label) cell.setAttribute('scope', 'row');
      if (span > 1) cell.colSpan = span;
      cell.textContent = String(value ?? '').slice(0, label ? 30 : 1600);
      tr.appendChild(cell);
    }
    body.appendChild(tr);
  };
  row([[true,'教师'],[false,details.teacher],[true,'学生'],[false,details.student],[true,'上课时间'],[false,details.time]]);
  row([[true,'学科'],[false,details.subject],[true,'年级'],[false,details.grade],[true,'课题名称'],[false,details.title]]);
  row([[true,'学习目标'],[false,details.objectives,5]]);
  table.appendChild(body); header.appendChild(table);
  const band = doc.createElement('div');
  band.className = 'mwb-trial-content-label'; band.textContent = '内容';
  header.appendChild(band);
  return header;
}

